{"_": "Message", "id": 103, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-03-18 10:43:54+00:00", "message": "📌 Динамика инфляции.

По недельным оценкам, с начала марта инфляция значимо ускорилась. На текущей динамике цен во многом отражается всплеск потребительского спроса на отдельные группы товаров на фоне возросшей неопределенности и роста инфляционных ожиданий, а также произошедшее с начала 2022 года ослабление рубля.

Адаптация бизнеса к изменившимся внешним условиям, в том числе перестройка производственных и логистических цепочек, станет определяющим фактором на горизонте ближайших кварталов.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 18}], "views": 71508, "forwards": 88, "replies": null, "edit_date": "2022-03-18 10:43:58+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤬"}, "count": 341, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 174, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😢"}, "count": 56, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 22, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 20, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 8, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 7, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤩"}, "count": 6, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤯"}, "count": 5, "chosen_order": null}, {"_": "ReactionCount", "reaction": {