{"_": "Message", "id": 158, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-03-30 14:13:15+00:00", "message": "📄 Для ограничения влияния санкционных рисков Банк России скорректировал формат публикации данных о международных резервах Российской Федерации и управлении активами в иностранных валютах и золоте.

Начиная с 31 марта 2022 года мы возобновим публикацию показателя общего объема международных резервов Российской Федерации на еженедельной и ежемесячной основе.

Данные об управлении активами в иностранных валютах и золоте на 1 января 2022 года будут опубликованы в Годовом отчете Банка России за 2021 год. Публикация обзоров деятельности Банка России по управлению активами в иностранных валютах и золоте за период с 1 января 2022 года приостанавливается.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 194}], "views": 101519, "forwards": 114, "replies": null, "edit_date": "2022-03-30 14:13:24+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 516, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 104, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 57, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 53, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 23, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 14, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤯"}, "count": 8, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👏"}, "count": 5, "chosen_order": null}, {"_": "ReactionCount", "reac