{"_": "Message", "id": 166, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-04-01 13:57:31+00:00", "message": "📃Договоры страхования все чаще заключаются удаленно, и все больше нелегальных компаний и посредников пытаются этим воспользоваться. При этом чаще мошенничество происходит в сфере электронного ОСАГО, где преступники продают полисы с недостоверными сведениями.

Ущерб от мошенничества при заключении электронных договоров ОСАГО составляет не менее 4,2 млрд рублей в год. Он включает потери как автовладельцев из-за присвоения их средств мошенниками, так и страховщиков из-за недополученных страховых взносов.

Подробнее об этом, а также о причинах развития кибермошенничества в страховании и мерах борьбы с ними — в докладе.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": false, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityTextUrl", "offset": 613, "length": 9, "url": "http://www.cbr.ru/Content/Document/File/134881/information_report_20220401.pdf"}], "views": 128012, "forwards": 107, "replies": null, "edit_date": "2022-04-01 14:05:25+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 199, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 63, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 45, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😱"}, "count": 27, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 13, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😢"}, "count": 6, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 5, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 4, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤯"}, "count": 2, "chosen_order": null}], "min"