{"_": "Message", "id": 219, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-04-21 13:33:58+00:00", "message": "🌨 Банк России обновил сценарии обязательного стресс-тестирования негосударственных пенсионных фондов (НПФ).

Сценарии будут использоваться для тестирования портфелей фондов по состоянию на 31 марта 2022 года или на более позднюю дату. 

Основные изменения касаются динамики фондовых индексов, доходности российских и зарубежных государственных облигаций, спреда доходности корпоративных облигаций, ставок денежного рынка. Сценарии адаптированы к текущим условиям и не создают дополнительной нагрузки на НПФ.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityTextUrl", "offset": 15, "length": 16, "url": "http://www.cbr.ru/Collection/Collection/File/40947/20220420_od-798.pdf"}], "views": 80787, "forwards": 41, "replies": null, "edit_date": "2022-04-21 13:34:16+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 190, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 48, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 31, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 9, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤯"}, "count": 9, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 5, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👏"}, "count": 4, "chosen_order": null}], "min": false, "can_see_list": false, "reactions_as_tags": false, "recent_reactions":