l}], "min": false, "can_see_list": false, "reactions_as_tags": false, "recent_reactions": [], "top_reactors": []}, "restriction_reason": [], "ttl_period": null, "quick_reply_shortcut_id": null, "effect": null, "factcheck": null, "report_delivery_until_date": null, "paid_message_stars": null, "suggested_post": null}

{"_": "Message", "id": 282, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-05-25 07:10:12+00:00", "message": "🌗 Приток рублевых вкладов населения (+1,3 трлн руб.) в апреле практически полностью компенсировал совокупный отток в феврале — марте. Вместе с размещением госсредств это позволило банкам снизить объем заимствований от ЦБ до докризисного уровня.

Кредитование ожидаемо «поджалось» из-за снижения спроса на фоне роста ставок и экономической неопределенности, а также более осторожной позиции банков с учетом возросших кредитных рисков. Корпоративный портфель почти не изменился (-0,03%), а ипотечный немного сократился (-0,1%, по предварительным данным), при этом снизились выдачи как рыночной, так и льготной ипотеки. Продолжилось сокращение необеспеченного потребительского кредитования (по предварительным данным, −1,8%).

