5819, 36171, 54887, 107195]}], "dc_id": 4, "has_stickers": false, "video_sizes": []}, "embed_url": null, "embed_type": null, "embed_width": null, "embed_height": null, "duration": null, "author": "Глеб Каланов", "document": null, "cached_page": {"_": "Page", "url": "https://quote.ru/news/article/62ac49789a79479f825c5221", "blocks": [{"_": "PageBlockCover", "cover": {"_": "PageBlockPhoto", "photo_id": 5865099209777196515, "caption": {"_": "PageCaption", "text": {"_": "TextEmpty"}, "credit": {"_": "TextPlain", "text": "Вячеслав Прокофьев / ТАСС"}}, "url": null, "webpage_id": null}}, {"_": "PageBlockTitle", "text": {"_": "TextPlain", "text": "ЦБ предложил механизмы выхода частных инвесторов из замороженных акций"}}, {"_": "PageBlockAuthorDate", "author": {"_": "TextPlain", "text": "Глеб Каланов"}, "published_date": "2022-06-17 10:03:57+00:00"}, {"_": "PageBlockParagraph", "text": {"_": "TextBold", "text": {"_": "TextPlain", "text": "Первый зампред ЦБ Владимир Чистюхин поделился мнением, как можно решить проблему заблокированных в НРД иностранных акций, и оценил их объем в ₽6 трлн"}}}, {"_": "PageBlockParagraph", "text": {"_": "TextPlain", "text": "В ЦБ рассматривают возможные механизмы выхода частных инвесторов из принадлежащих россиянам, но замороженных в Национальном расчетном депозитарии (НРД) акций иностранных компаний. Об этом заявил журналистам первый зампред ЦБ Владимир Чистюхин в кулуарах Петербургского международного экономического форума — 2022 (ПМЭФ). Общая стоимость заблокированных в НРД бумаг, по его словам, оценивается в 6 трлн руб."}}, {"_": "PageBlockParagraph", "text": {"_": "TextConcat", "texts": [{"_": "TextPlain", "text": "«Надо дать возможность выйти из замороженных активов как минимум розничным инвесторам. Обсуждаются разные варианты. Один из них — выпуск неких производных инструментов на эти активы, которые приобретать смогут только «квалы» (квалифицированные инвесторы. — "}, {"_": "TextItalic", "text": {"_": "TextPlain", "text": "«РБК Инвестиции»"}}, {"_": "TextPlain", "text": "), а вот продавать — все владельцы тех бумаг», — сказал Чистюхин."}]}}, {"_": "PageBlockParagraph", "text": {"_": "TextPlain", "text": "Первый зампред ЦБ добавил, что ему нравится идея консолидации этих активов у крупного игрока, который не подпал под санкции и мог бы участвовать в переговорном процессе: «Не решено, может быть, это будет фонд, а может, и не фонд». Один из дальнейших вариантов — начать широкомасштабную работу с инвесторами по обмену таких активов. При этом Чистюхин отметил, что обращение индивидуальных инвесторов в зарубежные суды — это «сложный и экстенсивный» путь."}}, {"_": "PageBlockParagraph", "text": {"_": "TextPlain", "text": "НРД — центральный депозитарий России. Он ведет учет прав собственности на российские ценные бумаги, которыми владеют инвесторы, и проводит расчеты по сделкам. Кроме того, НРД — промежуточное звено хранения некоторых иностранных ценных бумаг, которые торгуются на СПБ Бирже и Мосбирже. Он имеет счета в международных депозитариях Euroclear и Clearstream. Помимо этого, НРД стал платежным агентом по еврооблигациям России, так как с 24 мая Citibank прекратил выполнять эти функции."}}, {"_": "PageBlockParagraph", "text": {"_": "TextPlain", "text": "3 июня Евросоюз ввел санкции против НРД. В ЕС заявили, что это крупнейший депозитарий ценных бумаг России, он играет ключевую роль в функционировании российской финансовой системы и связи последней с международной системой, «следовательно, прямо или косвенно включен в деятельность, политику и ресурсы российского правительства». Ранее НРД уже пострадал от блокировки счетов в Euroclear и Clearstream."}}, {"_": "PageBlockDivider"}, {"_": "PageBlockParagraph", "text": {"_": "TextConcat", "texts": [{"_": "TextPlain", "text": "Следите за новостями компаний в нашей группе в сети "}, {"_": "TextUrl", "text": {"_": "TextPlain", "text": "«ВКонтакте»"}, "url": "https://vk.com/rbc_investments", "webpage_id": 0}]}}, {"_": "PageBlockRelatedArticles", "title": {"_": "TextEmpty"}, "articles": [{"_": "PageRelatedArticle", "url": "https://quote.ru/news/article/629a30349a79473eb9e76922", "webpage_id": 3442933570491517642, "title": "НРД под санкциями ЕС. Что можно и нельзя делать с бумагами России и США", "description": "Национальный расчетный депозитарий подпал под санкции Евросоюза. Ранее он уже пострадал от блокировки счетов в Euroclear и Clearstream. Разбираемся, изменят ли ситуацию новые ограничения и отразятся ли они на инвесторах ...", "photo_id": 5826960664692895229, "author": "Александра Хрисанфова, Ксения Котченко, Дмитрий Полянский", "published_date": "2022-06-04 06:00:41+00:00"}]}], "photos": [{"_": "Photo", "id": 5826960664692895229, "access_hash": 6442056907972881862, "file_reference": "b'\x00it\xf7\x82\x92\x92\xbdC\xa89\xc2\xc7X\xf3\xf0c\x97r\x06\xce'", "date": "2022-06-04 06:01:41+00:00", "sizes": [{"_": "PhotoStrippedSize", "type": "i", "bytes": "b'\x01\x19(\xa6\xacA\x00\xfc\xbfZ\xb0\x85\x02\xb6NNx`x\xa6\x85\x07\xad\x0f\x1a\xa3\x06\x88\x93\x91\xf3\x0fZ\xe9\x96\xf69\xae\x9a\x1f g!\x8e\x1f\x03\x184G\x13\x15-\x1c\x9eY\x07\xee\xe7\x1f\xad$L\x01\xc7\xf0\xf6>\x95r(\xc6I\xe0\xabu\xa9\x95\xa2\xb4\x04\xdbcD\x97\x0b\x19\x05\xf2}v\xf3E<\xa1\x8f\x81\xca\x0e\x94RVz\x8d\xb9.\xa5\x10\xad\x9e\xbc{\xd2\xc8\x19c;z\xd5Y?\xd7\x1a\xbc\xbf\xea\xd6\xad\xea+X\x82\x03\x9d\xad ;\x0f\xf1\x03\xd2\xad\xa0\xf9\xb3\x13\x92\xa7\xa15\x12\x7f\xc8>/\xa9\xfeu-\x87\xfa\xa3\xf55.7W\xb9orA!\x07l\xa3\x9fZ(\x9f\xa1\xa2\x84\x88m\xa3'"}, {"_": "PhotoSize", "type": "m", "w": 320, "h": 200, "size": 28401}, {"_": "PhotoSize", "type": "x", "w": 800, "h": 500, "size": 157394}, {"_": "PhotoSizeProgressive", "type": "y", "w": 1200, "h": 750, "sizes": [16310, 58073, 106247, 162690, 283345]}], "dc_id": 4, "has_stickers": false, "video_sizes": []}], "documents": [], "part": false, "rtl": false, "v2": false, "views": null}, "attributes": []}, "force_large_media": false, "force_small_media": false, "manual": false, "safe": true}, "reply_markup": null, "entities": [{"_