{"_": "Message", "id": 355, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-06-24 12:59:55+00:00", "message": "📃 Российским резидентам не требуется получать индивидуальное разрешение Банка России на оплату долей, вкладов и паев в имуществе нерезидентов, если средства вносятся в рублях или валюте дружественного государства. Если оплата производится в валюте недружественного государства, сумма такой операции не должна превышать 15 млн рублей в эквиваленте.

Аналогичные требования распространяются и на взносы нерезидентам по договорам простого товарищества.

Раньше такие операции были возможны без получения индивидуального разрешения Банка России при внесении средств в пользу резидентов только из дружественных стран в валюте дружественного государства или в рублях на сумму не более 10 млн рублей.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityTextUrl", "offset": 25, "length": 21, "url": "https://cbr.ru/Content/Document/File/138679/20220623_prg.pdf"}], "views": 114486, "forwards": 321, "replies": null, "edit_date": "2022-06-24 13:00:13+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 134, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 56, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 21, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 6, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👏"}, "count": 5, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 3, "chosen_order": null}], "min": false, "can_see_list": false, "reactions_as_tags": false, "recent_reactions": [], "top_reactors": []}, "restriction_reason": [], "ttl_period": null, "quick_reply_shortcut_id": null, "effect": null, "factcheck": null, "report