{"_": "Message", "id": 374, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-07-06 09:10:48+00:00", "message": "🌾Банк России одобрил первый российский товарный индекс

Пилотным ценовым показателем стал биржевой индекс на пшеницу, который ежедневно по итогам торгов рассчитывает АО «Национальная товарная биржа». Он отражает стоимость тонны пшеницы на условиях поставки до порта Новороссийск. 

Для участников рынка индекс является ориентиром, который они могут использовать для решения своих бизнес-задач и запуска инструментов хеджирования ценовых рисков. Также его можно применять при регулировании товарных рынков.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 2, "length": 12}, {"_": "MessageEntityTextUrl", "offset": 14, "length": 7, "url": "https://www.cbr.ru/press/event/?id=13986"}, {"_": "MessageEntityBold", "offset": 21, "length": 34}], "views": 83354, "forwards": 181, "replies": null, "edit_date": "2022-07-06 09:10:54+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 385, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 52, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 33, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 25, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👏"}, "count": 10, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 7, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 5, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "Reactio