{"_": "Message", "id": 532, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-09-19 10:53:23+00:00", "message": "🏗 Новые макропруденциальные требования по ипотеке с низким первоначальным взносом на первичном рынке жилья

Банк России установил с 1 декабря 2022 года надбавку  к коэффициенту риска по ипотечным кредитам в рублях, предоставленным на финансирование по договору участия в долевом строительстве, с первоначальным взносом не выше 10%. Величина надбавки составит 2,0 вне зависимости от значения показателя долговой нагрузки заемщика. 

Эта мера направлена на ограничение практик предоставления таких кредитов, что позволит избежать накопления чрезмерных рисков в банковском секторе.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 104}, {"_": "MessageEntityTextUrl", "offset": 121, "length": 9, "url": "https://www.cbr.ru/press/pr/?file=19092022_142000RISKWEIGHTS19092022_132324.htm"}], "views": 84059, "forwards": 264, "replies": null, "edit_date": "2022-09-19 10:53:39+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 171, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 65, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 27, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😱"}, "count": 11, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 9, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤯"}, "count": 5, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 2, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👏"}, "count": 1, "chosen_order": null}, {"_": "ReactionCount", "reactio