{"_": "Message", "id": 546, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-09-28 09:05:00+00:00", "message": "📚Преподавание финансовой грамотности станет обязательным в старших классах школ

Ученики 10–11 классов на уроках обществознания узнают о том, как устроен и регулируется финансовый рынок, финансовых технологиях, причинах и последствиях инфляции. Старшеклассники также будут изучать правила обращения с личными финансами и узнают, как защититься от финансовых мошенников. Школьные программы должны быть адаптированы к новым требованиям стандартов к 1 сентября 2023 года. В 1–9 классах преподавание основ финансовой грамотности стало обязательным с начала 2022/23 учебного года. Оно ведется на уроках математики, информатики, окружающего мира, обществознания и географии.

🖇Финансовая грамотность включена в федеральные образовательные стандарты для старшей школы приказом Министерства просвещения России. Работа над этими изменениями шла при экспертном участии Банка России и Министерства финансов России.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": false, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 2, "length": 78}, {"_": "MessageEntityTextUrl", "offset": 773, "length": 31, "url": "https://t.me/minprosrf"}, {"_": "MessageEntityTextUrl", "offset": 877, "length": 28, "url": "https://t.me/minfin"}], "views": 87341, "forwards": 430, "replies": null, "edit_date": "2022-09-28 10:20:28+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 567, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 58, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 25, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 16, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 14, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 3, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🎉"}, "count": 2, "chosen_order": null}, {"_": "ReactionCount