{"_": "Message", "id": 608, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2022-10-25 13:01:03+00:00", "message": "❗️Мобилизованные смогут досрочно отказаться от ОСАГО и вернуть часть премии

Для досрочного расторжения договора ОСАГО и возврата части стоимости полиса за неиспользованный период мобилизованному нужно будет обратиться в страховую компанию с соответствующим заявлением. Это предусматривает проект указания Банка России, представленный на общественное обсуждение.

Такое заявление можно будет подать как в офисе страховой компании, так и онлайн — через личный кабинет на ее сайте — вне зависимости от того, каким образом ранее был приобретен полис. Досрочно отказаться от ОСАГО за мобилизованного сможет и другой человек по нотариальной доверенности, в которой будет прописано право досрочного расторжения договора.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 2, "length": 74}, {"_": "MessageEntityTextUrl", "offset": 290, "length": 28, "url": "https://cbr.ru/StaticHtml/File/41186/221025-53-1.pdf"}], "views": 92780, "forwards": 230, "replies": null, "edit_date": "2022-10-25 13:01:15+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 218, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 115, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 84, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤯"}, "count": 16, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 14, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😱"}, "count": 6, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😢"}