{"_": "Message", "id": 852, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2023-02-13 10:20:04+00:00", "message": "⬆️Банк России повышает с марта нормативы обязательных резервов

В условиях роста структурного профицита ликвидности и в целях сохранения тенденции на девалютизацию балансов кредитных организаций с 1 марта 2023 года по заранее анонсированному плану будут повышены нормативы обязательных резервов:

— на 1 п.п., до 4%, по всем категориям резервируемых обязательств в валюте Российской Федерации для банков с универсальной лицензией и небанковских кредитных организаций;

— на 2 п.п., до 7%, по всем категориям резервируемых обязательств в иностранной валюте для всех кредитных организаций.

Нормативы обязательных резервов по всем категориям резервируемых обязательств в валюте Российской Федерации для банков с базовой лицензией остаются без изменения.

Новые нормативы применяются начиная с регулирования размера обязательных резервов за март 2023 года.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 2, "length": 60}, {"_": "MessageEntityTextUrl", "offset": 248, "length": 14, "url": "https://cbr.ru/press/pr/?file=638118888428173728DKP.htm"}], "views": 55064, "forwards": 200, "replies": null, "edit_date": "2023-02-13 10:20:56+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 124, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 35, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 30, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 10, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 7, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 3, "chosen_order": null}], "min": false, "can_see_list": false, "reactions_as_tags": false, "recent_reactions": [], "top_reactors": []}, "restriction_reason": [], "ttl_period": null, "quick_reply_shortcut_id": null, "effect": null, "factcheck": null, "report_delivery_until_date": null, "paid_message_stars": null, "suggested_post": null}

