{"_": "Message", "id": 910, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2023-03-10 14:00:56+00:00", "message": "🧮 Банк России определил требования к расчету величины обязательств НПФ

Негосударственные пенсионные фонды (НПФ) будут пересчитывать этот показатель ежеквартально на основании прогноза своих денежных потоков. Новые требования касаются как договоров об обязательном пенсионном страховании, так и договоров негосударственного пенсионного обеспечения. Положение Банка России зарегистрировал Минюст России, оно вступает в силу с 1 января 2024 года. 

Документ определил единые подходы к методологии расчета и отражению полученных результатов. Планируется, что в дальнейшем они будут включаться в отчетность, учитываться при определении норматива страхового резерва, а также использоваться при подготовке актуарного заключения и проведения стресс-тестирования. Эти требования помогут улучшить контроль за финансовой устойчивостью фондов.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 70}, {"_": "MessageEntityTextUrl", "offset": 350, "length": 22, "url": "https://cbr.ru/Queries/UniDbQuery/File/90134/2743"}], "views": 59742, "forwards": 53, "replies": null, "edit_date": "2023-03-10 14:01:08+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 88, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 32, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 13, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 9, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 7, "chosen_order": null}], "min": false, "can_see_list": false, "reactions_as_tags": false, "recent_reactions": [], "top_reactors": []}, "restriction_reason": [], "ttl_period": null, "