{"_": "Message", "id": 935, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2023-03-21 07:33:31+00:00", "message": "❗️С 1 апреля меняются правила покупки неквалифицированными инвесторами некоторых иностранных ценных бумаг.

В частности речь идет о ценных бумагах дружественных эмитентов, если они учитываются в недружественном депозитарии. Брокер вправе исполнить поручение клиента только в случае, если уведомил клиента о возможной дальнейшей блокировке таких ценных бумаг. Брокер может либо перед каждой сделкой направлять сообщение клиенту с помощью push-уведомлений, либо однократно проинформировать его о правилах покупки и получить согласие на принятие риска.

При этом с 21 марта приостанавливается допуск к организованным торгам ПАО «СПБ Биржа» новых иностранных ценных бумаг, разрешенных для неквалифицированных инвесторов, если они учитываются в недружественном депозитарии.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 2, "length": 103}], "views": 159198, "forwards": 459, "replies": {"_": "MessageReplies", "replies": 78, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 596061215}, {"_": "PeerUser", "user_id": 1637228701}, {"_": "PeerUser", "user_id": 5291859751}], "channel_id": 1910507424, "max_id": 2696, "read_max_id": null}, "edit_date": "2023-03-21 07:33:46+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 130, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 72, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 24, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 14, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 11, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😢"}, "count": 4, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "Rea