ull}, "reply_markup": null, "entities": [{"_": "MessageEntityTextUrl", "offset": 127, "length": 7, "url": "https://frankmedia.ru/123506?utm_source=ti"}, {"_": "MessageEntityMention", "offset": 785, "length": 10}], "views": 36751, "forwards": 101, "replies": {"_": "MessageReplies", "replies": 80, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerChannel", "channel_id": 1972178465}, {"_": "PeerChannel", "channel_id": 1910507424}, {"_": "PeerUser", "user_id": 1144325384}], "channel_id": 1910507424, "max_id": 30692, "read_max_id": null}, "edit_date": "2023-05-16 09:50:30+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 176, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 50, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 20, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👏"}, "count": 19, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 17, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😢"}, "count": 14, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 4, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 3, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤯"}, "count": 3, "chosen_order": null}], "min": false, "can_see_list": false, "reactions_as_tags": false, "recent_reactions": [], "top_reactors": []}, "restriction_reason": [], "ttl_period": null, "quick_reply_shortcut_id": null, "effect": null, "factcheck": null, "report_delivery_until_date": null, "paid_message_stars": null, "suggeste