{"_": "Message", "id": 1116, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2023-06-19 10:36:33+00:00", "message": "💬 «Когда кто-то предлагает запретить выдавать микрозаймы, то он не очень понимает, что миллионы людей, которые ими пользуются, делают это по своим причинам. Например, рядом нет банка или он есть, но отказывает в кредите, а может, просто нужно занять на короткий срок.

Если мы запретим этим людям брать микрозаймы, то будем подталкивать их к нелегальным кредиторам, в серую зону, которая, к сожалению, существует. А там не действуют механизмы защиты, которую выстроил законодатель в части прав конкретного заемщика».

Заместитель Председателя Банка России Филипп Габуния в интервью «Известиям» — о том, почему нельзя ограничивать количество микрозаймов на человека и чем может быть привлекательна программа долгосрочных сбережений.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5819147036393475340}, {"_": "MessageEntityItalic", "offset": 4, "length": 513}, {"_": "MessageEntityBold", "offset": 556, "length": 15}, {"_": "MessageEntityTextUrl", "offset": 574, "length": 20, "url": "https://cbr.ru/press/event/?id=15847"}], "views": 43260, "forwards": 116, "replies": {"_": "MessageReplies", "replies": 170, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 420459704}, {"_": "PeerUser", "user_id": 6043652720}, {"_": "PeerUser", "user_id": 837234667}], "channel_id": 1910507424, "max_id": 16310, "read_max_id": null}, "edit_date": "2023-06-19 10:36:42+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 258, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 170, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 39, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 31, "chosen_order": null}, {"_": "R