{"_": "Message", "id": 1133, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2023-06-23 14:52:35+00:00", "message": "☔️ Банк России предлагает уточнить требования к стресс-тестированию НПФ

Изменения направлены на совершенствование оценки рисков при исполнении обязательств негосударственными пенсионными фондами (НПФ) перед своими клиентами. Это позволит лучше оценивать финансовую устойчивость таких институтов. Проект указания Банка России опубликован для общественного обсуждения.

Для более точного отражения финансового положения фондов предлагается учитывать не только их вознаграждение и расходы, возникающие при инвестировании средств, но и общехозяйственные затраты, которые они несут при исполнении договоров негосударственного пенсионного обеспечения и договоров об обязательном пенсионном страховании.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 2, "length": 69}, {"_": "MessageEntityBold", "offset": 72, "length": 1}, {"_": "MessageEntityTextUrl", "offset": 73, "length": 9, "url": "http://www.cbr.ru/press/event/?id=16861"}, {"_": "MessageEntityTextUrl", "offset": 297, "length": 28, "url": "http://www.cbr.ru/StaticHtml/File/41186/230623-38-1.pdf"}], "views": 48805, "forwards": 28, "replies": {"_": "MessageReplies", "replies": 3, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 122234667}, {"_": "PeerUser", "user_id": 347261330}, {"_": "PeerUser", "user_id": 231583729}], "channel_id": 1910507424, "max_id": 14613, "read_max_id": null}, "edit_date": "2023-06-23 14:53:26+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 63, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 19, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 17, "chosen_o