{"_": "Message", "id": 1145, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2023-07-03 07:15:27+00:00", "message": "💬 «В идеале необходимо иметь несколько инструментов, которые позволят расплачиваться безналичным образом нашим гражданам за рубежом и иностранным гостям здесь, в России.
Сегодня помимо работы, которую проводим мы и НСПК, рынок самостоятельно находит такие решения. Это касается Турции. Там такая возможность уже есть». 

Директор Департамента национальной платежной системы Банка России Алла Бакина в интервью «Известиям» — о трансграничных платежах, импортозамещении чипов и оборудования для приема карт, способах оплаты в одно касание и о том, когда ждать принятия законопроекта о цифровом рубле.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5819147036393475340}, {"_": "MessageEntityItalic", "offset": 3, "length": 317}, {"_": "MessageEntityBold", "offset": 387, "length": 12}, {"_": "MessageEntityTextUrl", "offset": 400, "length": 22, "url": "https://iz.ru/1532649/natalia-ilina/uzhe-piat-rossiiskikh-bankov-predlagaiut-uslugu-transgranichnogo-perevoda-cherez-sbp"}], "views": 45862, "forwards": 50, "replies": {"_": "MessageReplies", "replies": 80, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 6043652720}, {"_": "PeerUser", "user_id": 5027410598}], "channel_id": 1910507424, "max_id": 16473, "read_max_id": null}, "edit_date": "2023-07-03 07:16:03+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 116, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 61, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 8, "chosen_order": null}, {"_": "ReactionC