{"_": "Message", "id": 1486, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2023-12-21 12:40:51+00:00", "message": "💬 «Что касается удаленного урегулирования убытков в ОСАГО через Госуслуги, сейчас этим сервисом пользуется более тысячи автовладельцев в месяц. И это неплохой результат для старта. Учитывая популярность Европротокола (около 60-80 тысяч ДТП оформляются таким образом каждый месяц) и распространенность удаленного взаимодействия в других сферах жизни, есть большой потенциал роста числа пользователей этой услуги.

Мы планируем обновить форму извещения о ДТП, разместив на документе QR-код для перехода в мобильное приложение по электронному урегулированию убытков по ОСАГО. Уже подготовлен проект нормативного документа. Нововведение повысит осведомленность автомобилистов о дистанционном урегулировании убытков и упростит этот процесс».

Глава Департамента страхового рынка Банка России Илья Смирнов в интервью — о первых результатах электронного урегулирования убытков по ОСАГО, а также о том, как сработали меры поддержки на страховом рынке, и планах Банка России на ближайший год.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": false, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityItalic", "offset": 0, "length": 2}, {"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5819147036393475340}, {"_": "MessageEntityItalic", "offset": 2, "length": 735}, {"_": "MessageEntityBold", "offset": 788, "length": 12}, {"_": "MessageEntityTextUrl", "offset": 801, "length": 12, "url": "http://www.finmarket.ru/interview/?id=6093819"}], "views": 54683, "forwards": 59, "replies": {"_": "MessageReplies", "replies": 18, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 6554904665}, {"_": "PeerChannel", "channel_id": 1910507424}, {"_": "PeerUser", "user_id": 665477689}], "channel_id": 1910507424, "max_id": 68832, "read_max_id": null}, "edit_date": "2023-12-21 12:44:34+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 122, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 32, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 15, "chosen_order": null}, {"_": "ReactionCou