{"_": "Message", "id": 1518, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-01-11 07:08:56+00:00", "message": "👛 В Программе долгосрочных сбережений появился первый НПФ

Первым оператором Программы долгосрочных сбережений (ПДС) стал СберНПФ. Его правила по формированию долгосрочных сбережений зарегистрировал Банк России. У нас на рассмотрении находится еще 12 правил от негосударственных пенсионных фондов, которые готовы предлагать новый продукт.

ПДС стартовала с начала этого года. Она позволит людям получать дополнительный доход в будущем или создать подушку безопасности на случай особых жизненных ситуаций.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 55}, {"_": "MessageEntityTextUrl", "offset": 136, "length": 7, "url": "https://cbr.ru/press/event/?id=18345"}, {"_": "MessageEntityBold", "offset": 143, "length": 1}, {"_": "MessageEntityTextUrl", "offset": 381, "length": 8, "url": "https://t.me/centralbank_russia/1142"}], "views": 90249, "forwards": 269, "replies": {"_": "MessageReplies", "replies": 220, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 184632373}, {"_": "PeerUser", "user_id": 933501995}, {"_": "PeerChannel", "channel_id": 1972178465}], "channel_id": 1910507424, "max_id": 73729, "read_max_id": null}, "edit_date": "2024-01-11 07:09:07+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 146, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 90, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 57, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🤔"}, "count": 18, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "Reacti