{"_": "Message", "id": 1556, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-02-07 12:29:09+00:00", "message": "🌤 Банк России оценил влияние климатических рисков на банки и крупнейшие компании

При отсутствии проактивной адаптации к энергопереходу финансовое состояние трети рассмотренных компаний реального сектора ухудшается на горизонте 2030–2040 годов. Банки могут столкнуться с существенными потерями, если не изменится структура их кредитного портфеля. 

Результаты стресс-тестирования показали, что банкам следует наладить управление климатическими рисками в соответствии с рекомендациями. В том числе диверсифицировать собственный кредитный портфель и помогать производителям углеводородов и компаниям, производящим большой объем выбросов парниковых газов, перестроить свои бизнес-модели в условиях энергоперехода.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": false, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 78}, {"_": "MessageEntityItalic", "offset": 83, "length": 265}, {"_": "MessageEntityTextUrl", "offset": 350, "length": 30, "url": "https://cbr.ru/Content/Document/File/158608/info_07022024.pdf"}, {"_": "MessageEntityTextUrl", "offset": 470, "length": 14, "url": "https://cbr.ru/crosscut/lawacts/file/6556"}], "views": 48350, "forwards": 151, "replies": {"_": "MessageReplies", "replies": 58, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 5285170125}, {"_": "PeerUser", "user_id": 288173055}, {"_": "PeerUser", "user_id": 5984865824}], "channel_id": 1910507424, "max_id": 74551, "read_max_id": null}, "edit_date": "2024-02-07 12:31:31+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 91, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 57, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "Reac