{"_": "Message", "id": 1677, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-03-31 10:50:17+00:00", "message": "🔘 Банк России обновил сценарии обязательного стресс-тестирования негосударственных пенсионных фондов

Новые сценарии предполагают больший рост ставок денежного рынка и доходностей ОФЗ на коротких сроках по сравнению с показателями в предыдущем документе.

Сценарные параметры дополнены прогнозом курса китайского юаня к рублю. Предусмотрен также особый порядок определения группы кредитного качества (вероятности дефолта) активов, направленных на финансирование проектов технологического суверенитета и структурной адаптации российской экономики.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 98}, {"_": "MessageEntityTextUrl", "offset": 103, "length": 14, "url": "http://www.cbr.ru/Collection/Collection/File/49049/20240328_od-477.pdf"}], "views": 53205, "forwards": 85, "replies": {"_": "MessageReplies", "replies": 5, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerChannel", "channel_id": 1910507424}, {"_": "PeerUser", "user_id": 2119717123}, {"_": "PeerUser", "user_id": 6469886696}], "channel_id": 1910507424, "max_id": 83194, "read_max_id": null}, "edit_date": "2024-03-31 10:50:37+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 65, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 38, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 25, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 16, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionE