{"_": "Message", "id": 1909, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-07-30 12:13:11+00:00", "message": "🗣 «Что будет, если при нехватке ресурсов подстегивать спрос? Он просто весь уйдет в ускорение инфляции. А экономика начнет замедляться. Более того, возникнет риск свалиться в глубокую рецессию. При высокой и ускоряющейся инфляции экономика уязвима, она плохо слушается руля. И нам в наших обстоятельствах этого позволить нельзя. 

И не могу не сказать о людях. У многих в последнее время выросли реальные доходы. Это очень хорошо. Но не будем забывать и о тех людях, чьи и без того небольшие доходы не поспевают за инфляцией. Для них наша политика снижения инфляции — это не какая-то абстракция, а вопрос, смогут ли они прокормить себя, свою семью, выбраться из бедности». 

Эльвира Набиуллина выступила на Совете по развитию финансового рынка при Совете Федерации. Полный текст выступления читайте на нашем сайте.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5821302890932736039}, {"_": "MessageEntityItalic", "offset": 3, "length": 671}, {"_": "MessageEntityBold", "offset": 676, "length": 18}, {"_": "MessageEntityTextUrl", "offset": 800, "length": 14, "url": "https://cbr.ru/press/event/?id=18880"}], "views": 57297, "forwards": 142, "replies": {"_": "MessageReplies", "replies": 140, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 688562844}, {"_": "PeerChannel", "channel_id": 1972178465}, {"_": "PeerChannel", "channel_id": 1910507424}], "channel_id": 1910507424, "max_id": 101376, "read_max_id": null}, "edit_date": "2024-07-30 12:13:28+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 408, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 72, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 47, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 26, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon":