{"_": "Message", "id": 2006, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-09-17 10:19:41+00:00", "message": "🛟 Страховые организации смогут получить лицензию управляющей компании

Страховщик жизни сможет получить лицензию управляющей компании для долевого страхования жизни. Пошаговую инструкцию по получению такой лицензии, образцы заявления и анкеты должностного лица можно найти на сайте.

Долевое страхование жизни — новый для российского страхового рынка инвестиционный продукт, который станет способствовать привлечению долгосрочных инвестиций в экономику страны. В одном договоре будут сочетаться классическое страхование жизни клиента и управление его вложениями в паи ПИФ. Возможность страховых организаций осуществлять деятельность управляющей компании по долевому страхованию жизни с января 2025 года предусмотрена законом «Об инвестиционных фондах».", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 67}, {"_": "MessageEntityTextUrl", "offset": 89, "length": 15, "url": "https://www.cbr.ru/Queries/UniDbQuery/File/90134/4101"}, {"_": "MessageEntityTextUrl", "offset": 274, "length": 8, "url": "https://www.cbr.ru/admissionfinmarket/navigator/uk/#a_162181"}, {"_": "MessageEntityItalic", "offset": 285, "length": 419}, {"_": "MessageEntityTextUrl", "offset": 704, "length": 13, "url": "http://www.cbr.ru/press/event/?id=17289"}, {"_": "MessageEntityItalic", "offset": 704, "length": 13}, {"_": "MessageEntityItalic", "offset": 717, "length": 36}], "views": 69442, "forwards": 141, "replies": {"_": "MessageReplies", "replies": 76, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 5949723575}, {"_": "PeerChannel", "channel_id": 1972178465}], "channel_id": 1910507424, "max_id": 113842, "read_max_id": null}, "edit_date": "2024-09-17 10:19:59+00:00", "post_author": null, "grouped_id": null, "reactions"