{"_": "Message", "id": 2155, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-11-18 07:03:49+00:00", "message": "〰️ Банк России упростил требования к документам, которые кредитная организация должна представить регулятору, чтобы получить согласие на установление прямого или косвенного контроля над другой кредитной организацией

Вместо бизнес-плана теперь нужно представить оценку влияния сделки на дальнейшую деятельность и финансовую устойчивость кредитных организаций, участвующих в ней. Таким образом, не нужно будет утверждать бизнес-план или вносить в него изменения и проводить для этого общее собрание акционеров/участников.

Указания Банка России вступили в силу 17 ноября. Они внесли изменения в порядок представления бизнес-плана кредитной организации и в инструкцию о получении согласия регулятора на приобретение акций финансовой организации.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 4970096070001427263}, {"_": "MessageEntityBold", "offset": 3, "length": 212}, {"_": "MessageEntityItalic", "offset": 522, "length": 72}, {"_": "MessageEntityBold", "offset": 560, "length": 9}, {"_": "MessageEntityTextUrl", "offset": 594, "length": 21, "url": "http://www.cbr.ru/queries/unidbquery/file/90134/4146"}, {"_": "MessageEntityItalic", "offset": 594, "length": 21}, {"_": "MessageEntityItalic", "offset": 615, "length": 40}, {"_": "MessageEntityTextUrl", "offset": 655, "length": 31, "url": "http://www.cbr.ru/queries/unidbquery/file/90134/4147"}, {"_": "MessageEntityItalic", "offset": 655, "length": 31}, {"_": "MessageEntityItalic", "offset": 686, "length": 57}], "views": 54507, "forwards": 63, "replies": {"_": "MessageReplies", "replies": 40, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 1686835719}, {"_": "PeerUser", "user_id": 5173478981}, {"_": "PeerUser", "user_id": 7239041363}], "channel_id": 1910507424, "max_id": 133366, "read_max_id": null}, "edit_date": "2024-11-18 07:03:59+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCou