{"_": "Message", "id": 2195, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-11-29 09:20:43+00:00", "message": "🏠 Начинаем публиковать сезонно скорректированные ряды задолженности по ипотечным жилищным кредитам с учетом приобретенных прав требования в целом по России

Новая публикация дает возможность исключить влияние сезонного фактора при анализе динамики ипотечного портфеля и сформировать более четкое представление о значимых несезонных тенденциях в динамических рядах.

Данные будут размещаться в подразделе Показатели рынка жилищного (ипотечного  жилищного) кредитования и обновляться ежемесячно в соответствии с Календарем публикации официальной статистической информации.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5363840027245696377}, {"_": "MessageEntityBold", "offset": 3, "length": 153}, {"_": "MessageEntityTextUrl", "offset": 405, "length": 63, "url": "http://www.cbr.ru/statistics/bank_sector/mortgage/"}, {"_": "MessageEntityTextUrl", "offset": 511, "length": 59, "url": "http://www.cbr.ru/statistics/indcalendar/"}], "views": 76486, "forwards": 107, "replies": {"_": "MessageReplies", "replies": 169, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 1432172360}, {"_": "PeerChannel", "channel_id": 1910507424}, {"_": "PeerUser", "user_id": 6630671990}], "channel_id": 1910507424, "max_id": 149487, "read_max_id": null}, "edit_date": "2024-11-29 09:21:10+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 189, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 43, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 27, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoj