{"_": "Message", "id": 2268, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-12-24 10:33:07+00:00", "message": "🥶 Банки будут обязаны приостанавливать на два дня распоряжения клиентов об операциях с цифровыми рублями, если есть признаки мошенничества

Механизмы противодействия подозрительным операциям с цифровыми рублями аналогичны тем, которые уже действуют с 25 июля 2024 года для обычных переводов. При выявлении такой операции банк уведомит клиента о риске обмана и сообщит о возможности подтвердить ее не позднее следующего дня. Если клиент не подтвердит перевод — деньги останутся на его счете цифрового рубля (цифровом кошельке).

Порядок защиты граждан и организаций от переводов на счета мошенников утвержден указанием Банка России в соответствии с законом о национальной платежной системе. Указание вступит в силу 23 февраля 2025 года.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5343744824455487952}, {"_": "MessageEntityBold", "offset": 3, "length": 136}, {"_": "MessageEntityTextUrl", "offset": 240, "length": 9, "url": "http://www.cbr.ru/press/event/?id=18865"}, {"_": "MessageEntityItalic", "offset": 529, "length": 80}, {"_": "MessageEntityTextUrl", "offset": 609, "length": 9, "url": "http://www.cbr.ru/Queries/UniDbQuery/File/90134/6214"}, {"_": "MessageEntityItalic", "offset": 609, "length": 9}, {"_": "MessageEntityItalic", "offset": 618, "length": 118}], "views": 65966, "forwards": 238, "replies": {"_": "MessageReplies", "replies": 0, "replies_pts": 293503, "comments": true, "recent_repliers": [], "channel_id": 1910507424, "max_id": null, "read_max_id": null}, "edit_date": "2024-12-24 10:33:13+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 217, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 133, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5415811790112055254}, "count": 94, "chosen