{"_": "Message", "id": 2283, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2024-12-27 13:47:13+00:00", "message": "🐥 Банк России установил порядок выдачи лицензий иностранным банкам для работы их филиалов в России

Указание устанавливает порядок выдачи лицензии на проведение банковских операций, ее форму и порядок аккредитации филиала иностранного банка на территории Российской Федерации, а также состав сведений, включаемых в реестр.

Нормативный акт вступает в силу 7 января 2025 года. Закон, регламентирующий допуск иностранных банков через их филиалы, вступил в силу 1 сентября 2024 года.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": false, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5343954332960198281}, {"_": "MessageEntityBold", "offset": 3, "length": 98}, {"_": "MessageEntityTextUrl", "offset": 101, "length": 8, "url": "http://www.cbr.ru/Queries/UniDbQuery/File/90134/6224"}], "views": 71144, "forwards": 100, "replies": {"_": "MessageReplies", "replies": 127, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerChannel", "channel_id": 1910507424}, {"_": "PeerUser", "user_id": 1179932447}, {"_": "PeerUser", "user_id": 5754842253}], "channel_id": 1910507424, "max_id": 152240, "read_max_id": null}, "edit_date": "2024-12-27 15:17:43+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5415811790112055254}, "count": 165, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 73, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 40, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5972287720284755380}, "count": 28, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionE