{"_": "Message", "id": 2341, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2025-02-12 08:05:21+00:00", "message": "📖 Банк России определил основные принципы добросовестного поведения на финансовом рынке

В документе представлены правила, которых следует придерживаться участникам рынка. Они направлены на продвижение деловых и этических стандартов, формирование доверительной среды и защиту прав и интересов потребителей.

Принципы носят рекомендательный характер и могут внедряться в стандарты и кодексы саморегулируемых организаций, профессиональных ассоциаций (союзов) как полностью, так и по отдельности, а также могут стать основой корпоративной культуры финансовых организаций.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5807488863064559221}, {"_": "MessageEntityBold", "offset": 3, "length": 85}, {"_": "MessageEntityTextUrl", "offset": 92, "length": 10, "url": "https://www.cbr.ru/Crosscut/LawActs/File/9969"}], "views": 62903, "forwards": 216, "replies": {"_": "MessageReplies", "replies": 0, "replies_pts": 293503, "comments": true, "recent_repliers": [], "channel_id": 1910507424, "max_id": null, "read_max_id": null}, "edit_date": "2025-02-12 08:05:32+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 134, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "😁"}, "count": 41, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5415811790112055254}, "count": 31, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 23, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5972287720284755380}, "count": 19, 