{"_": "Message", "id": 2355, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2025-02-14 11:42:12+00:00", "message": "❗️ Банк России принял решения по макропруденциальным надбавкам по ипотечным кредитам и кредитам крупным компаниям с повышенной долговой нагрузкой

⚫️ С 1 марта снижены надбавки к коэффициентам риска по ипотечным кредитам.

⚫️ С 1 апреля установлена надбавка к коэффициентам риска в размере 20% на прирост кредитных требований к крупным компаниям с повышенной долговой нагрузкой.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 19}, {"_": "MessageEntityTextUrl", "offset": 22, "length": 7, "url": "https://cbr.ru/press/pr/?file=638751375299149478FINSTAB.htm"}, {"_": "MessageEntityBold", "offset": 22, "length": 7}, {"_": "MessageEntityBold", "offset": 29, "length": 116}, {"_": "MessageEntityCustomEmoji", "offset": 147, "length": 2, "document_id": 5415680394177558218}, {"_": "MessageEntityTextUrl", "offset": 160, "length": 7, "url": "https://cbr.ru/rbr/dir_decisions/rsd_2025-02-14_35_01/"}, {"_": "MessageEntityCustomEmoji", "offset": 223, "length": 2, "document_id": 5415680394177558218}, {"_": "MessageEntityTextUrl", "offset": 237, "length": 11, "url": "https://cbr.ru/rbr/dir_decisions/rsd_2025-02-14_35_02/"}], "views": 85201, "forwards": 262, "replies": {"_": "MessageReplies", "replies": 39, "replies_pts": 293503, "comments": true, "recent_repliers": [{"_": "PeerChannel", "channel_id": 1910507424}, {"_": "PeerUser", "user_id": 990915538}, {"_": "PeerUser", "user_id": 7440824155}], "channel_id": 1910507424, "max_id": 155782, "read_max_id": null}, "edit_date": "2025-02-14 11:42:24+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5972287