{"_": "Message", "id": 2366, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2025-02-17 14:06:26+00:00", "message": "💻 Банк России разработал онлайн-сервис, который предоставляет информацию о компаниях с признаками нелегальной деятельности

Сервис основан на API и позволяет автоматизировать получение актуальных данных из «Списка компаний с выявленными признаками нелегальной деятельности». Информацию можно получить по наименованию компании, ее ИНН, адресу или сайту за весь доступный период.

Это позволит обмениваться информацией с участниками финансового рынка и другими пользователями списка, а также облегчит компаниям работу со списком.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5972124206584828811}, {"_": "MessageEntityBold", "offset": 3, "length": 120}, {"_": "MessageEntityTextUrl", "offset": 125, "length": 6, "url": "http://www.cbr.ru/development/warning-list/"}, {"_": "MessageEntityTextUrl", "offset": 207, "length": 67, "url": "http://www.cbr.ru/inside/warning-list/"}, {"_": "MessageEntityItalic", "offset": 380, "length": 3}, {"_": "MessageEntityItalic", "offset": 384, "length": 144}], "views": 77606, "forwards": 496, "replies": {"_": "MessageReplies", "replies": 0, "replies_pts": 293503, "comments": true, "recent_repliers": [], "channel_id": 1910507424, "max_id": null, "read_max_id": null}, "edit_date": "2025-02-17 14:06:44+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 278, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5294219088413879657}, "count": 70, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5294334558609629375}, "count": 56, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 31