{"_": "Message", "id": 2745, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2025-07-08 14:32:41+00:00", "message": "⌛️ Наследников на полгода освободят от штрафных санкций за просрочку по кредитам их родственников

Банки и микрофинансовые организации с 1 сентября не смогут начислять неустойку, пени и штрафы на долги умершего заемщика, пока его родственники оформляют наследство. Такой закон приняла Госдума.

Запрет будет действовать 6 месяцев, если законом или решением суда не установлен другой срок для вступления в права наследования. Это правило распространяется как на договоры потребительского кредитования или займа умершего, так и на ипотечные кредиты.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityCustomEmoji", "offset": 0, "length": 2, "document_id": 5352902832896877477}, {"_": "MessageEntityBold", "offset": 3, "length": 94}, {"_": "MessageEntityTextUrl", "offset": 271, "length": 5, "url": "https://sozd.duma.gov.ru/bill/532254-8"}], "views": 127334, "forwards": 778, "replies": {"_": "MessageReplies", "replies": 0, "replies_pts": 293505, "comments": true, "recent_repliers": [], "channel_id": 1910507424, "max_id": null, "read_max_id": null}, "edit_date": "2025-07-08 14:33:04+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 460, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 72, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 46, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 41, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5294219088413879657}, "count": 29, "chosen_order": null}, {"_": "ReactionC