{"_": "Message", "id": 2795, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2025-07-24 14:56:23+00:00", "message": "💼 Как информировать инвесторов о сложных финансовых продуктах

Рекомендуется размещать информацию о таких продуктах в специальных разделах сайтов и мобильных приложений. Она будет доступна пользователю, после того как он подтвердит статус квалифицированного инвестора и ознакомится с рисками этих инструментов.

Рекомендации помогут снизить вероятность навязывания неквалифицированным инвесторам сложных финансовых инструментов, по которым можно получить убытки. Согласно законодательству, участникам финансового рынка запрещается предлагать неквалифицированным инвесторам ряд сложных финансовых продуктов.", "out": false, "mentioned": false, "media_unread": false, "silent": true, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 59}, {"_": "MessageEntityTextUrl", "offset": 64, "length": 34, "url": "https://cbr.ru/Crosscut/LawActs/File/10056"}, {"_": "MessageEntityItalic", "offset": 313, "length": 294}], "views": 64275, "forwards": 41, "replies": {"_": "MessageReplies", "replies": 1, "replies_pts": 293505, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 771229820}], "channel_id": 1910507424, "max_id": 165154, "read_max_id": null}, "edit_date": "2025-07-24 14:56:38+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 82, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👎"}, "count": 39, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 24, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5294219088413879657}, "count": 23, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 529