{"_": "Message", "id": 3185, "peer_id": {"_": "PeerChannel", "channel_id": 1680634724}, "date": "2025-12-18 11:43:23+00:00", "message": "❗️ Позиция Банка России о взыскании в суде убытков, причиненных незаконными действиями европейских банков

В связи с продолжающимися попытками властей Европейского союза осуществить незаконное изъятие/использование без согласия Банка России его активов, размещенных в финансовых институтах ЕС, реализуемыми в том числе путем установления бессрочной иммобилизации его активов, Банк России в соответствии с ранее заявленной позицией об обеспечении защиты своих интересов сообщает, что будет взыскивать с европейских банков в российском арбитражном суде убытки, обусловленные неправомерной блокировкой и использованием его активов, в объеме незаконно удерживаемых активов и упущенной выгоды.

Напомним, что ранее Банк России уже подал иск к Euroclear в Арбитражный суд города Москвы.", "out": false, "mentioned": false, "media_unread": false, "silent": false, "post": true, "from_scheduled": false, "legacy": false, "edit_hide": true, "pinned": false, "noforwards": false, "invert_media": false, "offline": false, "video_processing_pending": false, "paid_suggested_post_stars": false, "paid_suggested_post_ton": false, "from_id": null, "from_boosts_applied": null, "saved_peer_id": null, "fwd_from": null, "via_bot_id": null, "via_business_bot_id": null, "reply_to": null, "media": null, "reply_markup": null, "entities": [{"_": "MessageEntityBold", "offset": 3, "length": 102}, {"_": "MessageEntityTextUrl", "offset": 325, "length": 12, "url": "http://eur-lex.europa.eu/legal-content/EN/TXT/?uri=OJ:L_202502600"}, {"_": "MessageEntityTextUrl", "offset": 732, "length": 3, "url": "https://cbr.ru/press/pr/?file=639011266514123767TODAY.htm"}], "views": 130052, "forwards": 457, "replies": {"_": "MessageReplies", "replies": 1, "replies_pts": 293505, "comments": true, "recent_repliers": [{"_": "PeerUser", "user_id": 7808974447}], "channel_id": 1910507424, "max_id": 173179, "read_max_id": null}, "edit_date": "2025-12-18 11:43:32+00:00", "post_author": null, "grouped_id": null, "reactions": {"_": "MessageReactions", "results": [{"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "🔥"}, "count": 791, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "👍"}, "count": 491, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionEmoji", "emoticon": "❤"}, "count": 168, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5294219088413879657}, "count": 152, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "ReactionCustomEmoji", "document_id": 5294334558609629375}, "count": 80, "chosen_order": null}, {"_": "ReactionCount", "reaction": {"_": "Reactio